/**
 * generated by stackra gen from src/routes/product/ (product.route.ts and the page product.tsx,
 * bound by name), src/routes/site/site.layout.ts, src/config/seo.config.ts (the app defaults of
 * the SEO chain), src/config/i18n.config.ts and context.ts — do not edit
 * Purpose: the React Router framework-mode module for one route class: turns the class's `loader`
 *          and `meta` and the page beside it into the exports the router expects, building the
 *          RouteContext (`site` from the layout's loader, `query`/`action` over the request's
 *          public clients for the site's locale and market, `env`, the request's `t`, `params`,
 *          `search`, `path`, `href`) from the typed context keys. One such file exists per route
 *          class; this is the sample for `/store/:slug`.
 * Boundary: delegation only; the class owns every behaviour. There is no `headers` export: data is
 *           cached per query by its profile and every page is `private, no-cache` (the root
 *           middleware). The module imports no server-only code: the clients and the env arrive in
 *           the request's context, so React Router's client build keeps only `default` and `meta`.
 * Runtime: isomorphic
 */
import { routeAdapter } from "@stackra/navigation/router";
import type { Route } from "./+types/product";
import { Product } from "#src/routes/product/product";
import { ProductRoute } from "#src/routes/product/product.route";
import { SiteLayout } from "#src/routes/site/site.layout";
import { translatorFor } from "#stackra/i18n";
import { routeKeys } from "../context";

/**
 * The adapter binds the class, its layout and its page once; every export below delegates to it.
 * It builds the class through the container on the first request, never at import.
 */
const adapter = routeAdapter(ProductRoute, {
  layout: SiteLayout,
  component: Product,
  keys: routeKeys,
  t: translatorFor,
});

/** Reads the layout's `site` (one run per request), builds the context, runs the class's loader. */
export async function loader(args: Route.LoaderArgs) {
  return adapter.loader(args);
}

/**
 * The SEO chain, in order: seo.config.ts defaults (title template, site name, OG card) → the
 * route's static `seo` → `ProductRoute.meta(ctx)` → the tenant's SEO record. The adapter derives
 * canonical, hreflang alternates and `noindex` for a non-indexable site, and escapes every JSON-LD
 * block (`@stackra/seo`).
 */
export const meta: Route.MetaFunction = (args) => adapter.meta(args);

/** The page `product.tsx` with `{ data, params, search }` from this module's loader. */
export default function ProductRouteModule({ loaderData, params }: Route.ComponentProps) {
  return adapter.render({ loaderData, params });
}
